static const size_t th8_key0_size = sizeof(th8_key0_data);

/*
 *----------------------------------------------------------------------
 *
 * Th8_GetEmbeddedKey0 --
 *
 *	Return a pointer to the embedded key0 public key blob
 *	and its size in bytes.
 *
 * Why / How:
 *	Key0 is a secondary trust anchor used for key rotation
 *	and delegation.  Compiled into the binary as a static
 *	byte array generated by mkkey.tcl.
 *
 * Results:
 *	Pointer to the key blob (static storage).  *pnData is
 *	set to the blob size if pnData is non-NULL.
 *
 * Side effects:
 *	None.
 *
 *----------------------------------------------------------------------
 */

const unsigned char *
Th8_GetEmbeddedKey0(size_t *pnData)
{
    if (pnData) *pnData = th8_key0_size;
    return th8_key0_data;
}

